Use the active sheet and read A/B/D from the cached workbook. For each E2:E7 row, return the B value from the same row when D matches A; otherwise fall back to the nth occurrence of D in A, blanking numeric zeros. Then write plain values and apply the requested fill, Calibri font, and zero-as-blank number format to E2:E9.

```python
import shutil
import openpyxl
from openpyxl.styles import PatternFill, Font

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title] if ws.title in vals.sheetnames else vals.active

max_row = max(vws.max_row, ws.max_row, 9)

def key(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return float(v)
    return str(v).strip()

def is_zero(v):
    if isinstance(v, bool):
        return False
    if isinstance(v, (int, float)):
        return v == 0
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return False
        try:
            return float(s) == 0.0
        except ValueError:
            return False
    return False

A = [key(vws.cell(r, 1).value) for r in range(1, max_row + 1)]
B = [vws.cell(r, 2).value for r in range(1, max_row + 1)]
D = [key(vws.cell(r, 4).value) for r in range(1, max_row + 1)]

for r in range(2, 8):
    d = D[r - 1]
    result = None

    if d is not None:
        # Preferred: same-row match, as requested.
        if A[r - 1] == d:
            result = B[r - 1]
        else:
            # Fallback: nth occurrence of the lookup value in column A.
            cnt = sum(1 for i in range(2, r + 1) if D[i - 1] == d)
            seen = 0
            for s in range(2, max_row + 1):
                if A[s - 1] == d:
                    seen += 1
                    if seen == cnt:
                        result = B[s - 1]
                        break

            # Last resort: first match.
            if result is None:
                for s in range(2, max_row + 1):
                    if A[s - 1] == d:
                        result = B[s - 1]
                        break

    if is_zero(result):
        result = None

    if isinstance(result, str):
        result = result.strip()

    ws.cell(row=r, column=5).value = result
    print(r, repr(result))

fill = PatternFill(start_color="FCE4D6", end_color="FCE4D6", fill_type="solid")
font = Font(name="Calibri")
numfmt = "General;General;;@"

for r in range(2, 10):
    c = ws.cell(row=r, column=5)
    c.fill = fill
    c.font = font
    c.number_format = numfmt

wb.save(OUT)
